// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
   scene triangle P1P2P3   → Mesh(BufferGeometry 3 verts) MeshBasic #F5A623 DoubleSide
   scene tri outline       → 3 × CylinderGeometry tubes r=0.035u black + joint caps
   P1/P2/P3 discs          → Sphere(0.18u) colour + Sphere(0.23u) black BackSide rim
   image plane (z=f)       → Mesh(quad, x[-1.1,2.3] y[-1.3,2.0]) white opacity .15 DoubleSide
   image plane border      → 4 × Cylinder tubes r=0.022u black
   small (projected) tri   → Mesh(BufferGeometry 3 verts) #F5A623 + 3 tubes r=0.017u black
   observed dots p_i       → Sphere(0.07u) colour + black rim + white halo (drag highlight)
   reprojected dots p_i'   → Sphere(0.055u) colour + black rim
   residual segments       → 3 × Cylinder tubes r=0.025u pure red #FF0000 (rebuilt on update)
   projection rays P_i→C   → Line + LineDashedMaterial dash .12u/.08u black
   camera centre C         → Sphere(0.07u) black
   camera triad X_L,Y_L,Z_L→ Cylinder shaft + Cone head, green #39B54A, length 1.3u
   image-plane triad       → Cylinder + Cone, green, length 0.45u, at centroid of small triangle
   optical-axis segment    → Cylinder tube r=0.012u black, C → image triad origin
   all text                → addLabel(), bold serif, white halo
   ( "u" = camera-frame unit; world = u × S so the whole figure stays compact )
   ─────────────────────────────────────────────────────────────────────────── */

const ORANGE = 0xF5A623, C_RED = 0xED1C24, C_CYAN = 0x29ABE2, C_GREEN = 0x22B14C;
const G_TRIAD = 0x39B54A, RES_RED = 0xFF0000;
const S = 0.42;                      // camera-unit → world-unit scale (keeps bbox compact)
const F_TRUE = 3.0, ZP = 3.0;
const RECT = { x0: -1.1, x1: 2.3, y0: -1.3, y1: 2.0 };

// camera(X_L,Y_L,Z_L) → world.  z is mirrored so the standard isometric pose
// reproduces the printed layout (depth to the upper-right, scene triangle upper-right).
const Wc = (x, y, z) => new THREE.Vector3(x * S, y * S, -z * S);
const IMG = (u, v) => Wc(u, v, ZP);

// Scene points chosen so f·(X/Z, Y/Z) reproduces the printed image points
// p1≈(1.40,1.13)  p2≈(0.60,-0.60)  p3≈(-0.17,1.28) while keeping the triangle
// close enough to the image plane that the whole figure frames large.
const Pw = [[2.80, 2.27, 6.00], [0.88, -0.88, 4.40], [-0.29, 2.14, 5.00]];
const COLS = [C_RED, C_CYAN, C_GREEN];
const obs = Pw.map(p => [F_TRUE * p[0] / p[2], F_TRUE * p[1] / p[2]]);
const est = [[0, 0], [0, 0], [0, 0]];
const resv = [0, 0, 0];

/* ── generic builders ─────────────────────────────────────────────────────── */
const _UP = new THREE.Vector3(0, 1, 0);

function makeTube(radius, color) {
  const geo = new THREE.CylinderGeometry(radius, radius, 1, 12);
  geo.translate(0, 0.5, 0);
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }));
  scene.add(m);
  return m;
}
function setTube(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  mesh.position.copy(a);
  mesh.scale.set(1, Math.max(len, 1e-6), 1);
  if (len > 1e-9) mesh.quaternion.setFromUnitVectors(_UP, dir.clone().normalize());
  mesh.visible = len > 1e-3;
}
function polyTube(points, radius, color) {
  for (let i = 0; i < points.length; i++) {
    setTube(makeTube(radius, color), points[i], points[(i + 1) % points.length]);
  }
  const jg = new THREE.SphereGeometry(radius, 12, 8);
  const jm = new THREE.MeshBasicMaterial({ color });
  points.forEach(p => { const s = new THREE.Mesh(jg, jm); s.position.copy(p); scene.add(s); });
}
function makeDot(radius, color, pos, halo) {
  const g = new THREE.Group();
  const core = new THREE.Mesh(new THREE.SphereGeometry(radius, 24, 16),
    new THREE.MeshBasicMaterial({ color }));
  const rim = new THREE.Mesh(new THREE.SphereGeometry(radius * 1.3, 24, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.BackSide }));
  g.add(core, rim);
  if (halo) {
    const h = new THREE.Mesh(new THREE.SphereGeometry(radius * 2.0, 24, 16),
      new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.BackSide }));
    h.visible = false; g.add(h); g.userData.halo = h;
  }
  g.position.copy(pos);
  scene.add(g);
  return g;
}
function makeArrow(origin, dir, length, color, shaftR, headR, headL) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, length - headL, 14), mat);
  shaft.position.y = (length - headL) / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 18), mat);
  head.position.y = length - headL / 2;
  g.add(shaft, head);
  g.quaternion.setFromUnitVectors(_UP, dir.clone().normalize());
  g.position.copy(origin);
  scene.add(g);
  return g;
}
function triMesh(color) {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
  geo.setIndex([0, 1, 2]);
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  scene.add(m);
  return m;
}
function setTriVerts(mesh, vs) {
  const a = mesh.geometry.attributes.position;
  for (let i = 0; i < 3; i++) a.setXYZ(i, vs[i].x, vs[i].y, vs[i].z);
  a.needsUpdate = true;
  mesh.geometry.computeBoundingSphere();
}

/* ── image plane (z = f) ──────────────────────────────────────────────────── */
const planeCorners = [
  IMG(RECT.x0, RECT.y1), IMG(RECT.x1, RECT.y1),
  IMG(RECT.x1, RECT.y0), IMG(RECT.x0, RECT.y0)
];
const planeGeo = new THREE.BufferGeometry();
planeGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
  planeCorners[0].x, planeCorners[0].y, planeCorners[0].z,
  planeCorners[1].x, planeCorners[1].y, planeCorners[1].z,
  planeCorners[2].x, planeCorners[2].y, planeCorners[2].z,
  planeCorners[3].x, planeCorners[3].y, planeCorners[3].z
]), 3));
planeGeo.setIndex([0, 1, 2, 0, 2, 3]);
const planeMesh = new THREE.Mesh(planeGeo, new THREE.MeshBasicMaterial({
  color: 0xffffff, side: THREE.DoubleSide, transparent: true, opacity: 0.15, depthWrite: false
}));
scene.add(planeMesh);
polyTube(planeCorners, 0.022 * S, 0x000000);

/* ── big scene triangle + 3D points ───────────────────────────────────────── */
const Pworld = Pw.map(p => Wc(p[0], p[1], p[2]));
const bigTri = triMesh(ORANGE);
setTriVerts(bigTri, Pworld);
polyTube(Pworld, 0.035 * S, 0x000000);
const Pdots = Pworld.map((v, i) => makeDot(0.18 * S, COLS[i], v, false));

/* ── dashed projection rays P_i → C ───────────────────────────────────────── */
Pworld.forEach(v => {
  const g = new THREE.BufferGeometry().setFromPoints([v, new THREE.Vector3(0, 0, 0)]);
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({
    color: 0x000000, dashSize: 0.12 * S, gapSize: 0.08 * S
  }));
  l.computeLineDistances();
  scene.add(l);
});

/* ── small projected triangle, observed / reprojected dots, residuals ─────── */
const smallTri = triMesh(ORANGE);
const smallOutline = [0, 1, 2].map(() => makeTube(0.017 * S, 0x000000));
const obsDots = obs.map((o, i) => makeDot(0.07 * S, COLS[i], IMG(o[0], o[1]), true));
const estDots = obs.map((o, i) => makeDot(0.055 * S, COLS[i], IMG(o[0], o[1]), false));
const resTubes = [0, 1, 2].map(() => makeTube(0.025 * S, RES_RED));

/* ── camera centre, triads, optical axis ──────────────────────────────────── */
const Corigin = new THREE.Vector3(0, 0, 0);
makeDot(0.07 * S, 0x000000, Corigin, false);
const AXL = 1.3 * S;
makeArrow(Corigin, new THREE.Vector3(1, 0, 0), AXL, G_TRIAD, 0.055 * S, 0.15 * S, 0.33 * S); // X_L
makeArrow(Corigin, new THREE.Vector3(0, 1, 0), AXL, G_TRIAD, 0.055 * S, 0.15 * S, 0.33 * S); // Y_L
makeArrow(Corigin, Wc(0, 0, 1), AXL, G_TRIAD, 0.055 * S, 0.15 * S, 0.33 * S);                // Z_L

const imgTriad = new THREE.Group();
scene.add(imgTriad);
imgTriad.add(makeArrow(new THREE.Vector3(), new THREE.Vector3(1, 0, 0), 0.45 * S, G_TRIAD, 0.022 * S, 0.062 * S, 0.13 * S));
imgTriad.add(makeArrow(new THREE.Vector3(), new THREE.Vector3(0, 1, 0), 0.45 * S, G_TRIAD, 0.022 * S, 0.062 * S, 0.13 * S));
const opticalAxis = makeTube(0.012 * S, 0x000000);

/* ── camera framing (after all geometry) ──────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.85
});
{
  const az0 = controls.getAzimuthalAngle(), po0 = controls.getPolarAngle();
  const dA = THREE.MathUtils.degToRad(40), dP = THREE.MathUtils.degToRad(30);
  controls.minAzimuthAngle = az0 - dA; controls.maxAzimuthAngle = az0 + dA;
  controls.minPolarAngle = Math.max(0.06, po0 - dP);
  controls.maxPolarAngle = Math.min(Math.PI - 0.06, po0 + dP);
  controls.enablePan = false;
}

/* ── labels ───────────────────────────────────────────────────────────────── */
const SERIF = 'Georgia,"Times New Roman",serif';
function lbl(html, pos, opts) {
  const e = addLabel(html, pos, opts || {});
  e.div.style.fontFamily = SERIF;
  e.div.style.textShadow = '0 0 3px #fff, 0 0 3px #fff, 0 0 3px #fff';
  return e;
}
lbl('<b>P</b><sub>1</sub>', Pworld[0], { fontSize: '23px', bold: true, offset: [40, -16] });
lbl('<b>P</b><sub>2</sub>', Pworld[1], { fontSize: '23px', bold: true, offset: [14, 36] });
lbl('<b>P</b><sub>3</sub>', Pworld[2], { fontSize: '23px', bold: true, offset: [-40, -14] });

const pLbl = [
  lbl('<b>p</b><sub>1</sub>', IMG(obs[0][0], obs[0][1]), { fontSize: '19px', bold: true, offset: [26, 18] }),
  lbl('<b>p</b><sub>2</sub>', IMG(obs[1][0], obs[1][1]), { fontSize: '19px', bold: true, offset: [-20, 22] }),
  lbl('<b>p</b><sub>3</sub>', IMG(obs[2][0], obs[2][1]), { fontSize: '19px', bold: true, offset: [-28, -4] })
];
const PRIME_HTML = [
  "<b>p</b>&prime;<sub>1</sub>", "<b>p</b>&prime;<sub>2</sub>", "<b>p</b>&prime;<sub>3</sub>"
];
const ePrimeLbl = [
  lbl(PRIME_HTML[0], IMG(0, 0), { fontSize: '18px', bold: true, offset: [-24, -16] }),
  lbl(PRIME_HTML[1], IMG(0, 0), { fontSize: '18px', bold: true, offset: [22, 18] }),
  lbl(PRIME_HTML[2], IMG(0, 0), { fontSize: '18px', bold: true, offset: [-26, -16] })
];
const rLbl = [
  lbl('', IMG(0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -13] }),
  lbl('', IMG(0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -13] }),
  lbl('', IMG(0, 0), { fontSize: '12px', color: '#c00000', offset: [0, -13] })
];
lbl('<i>X<sub>L</sub></i>', new THREE.Vector3(AXL * 1.14, 0, 0), { fontSize: '21px', offset: [12, 18] });
lbl('<i>Y<sub>L</sub></i>', new THREE.Vector3(0, AXL * 1.12, 0), { fontSize: '21px', offset: [-24, -4] });
lbl('<i>Z<sub>L</sub></i>', Wc(0, 0, 1.3 * 1.16), { fontSize: '21px', offset: [14, 20] });
lbl('<b>C</b>', Corigin, { fontSize: '16px', bold: true, offset: [-18, 15] });

/* ── explainers ───────────────────────────────────────────────────────────── */
registerInteractive(bigTri, {
  title: '3D scene points',
  tooltip: 'The 3D triangle P₁P₂P₃',
  body: 'Three known 3D points in the camera frame. They are fixed; only the camera model (K, R, T) is being estimated.'
});
registerInteractive(planeMesh, {
  title: 'Image plane (z = f)',
  tooltip: 'Image plane — where the error is measured',
  body: 'Reprojection error is a purely 2D quantity: it is measured on this plane, between the observed point p and the predicted point p′.'
});
Pdots.forEach((g, i) => registerInteractive(g, {
  title: 'P' + (i + 1),
  tooltip: 'Scene point P' + (i + 1),
  body: 'Camera-frame coordinates (' + Pw[i].join(', ') + '). Its true projection is p' + (i + 1) + ' = f·(X/Z, Y/Z).'
}));

/* ── state + update ───────────────────────────────────────────────────────── */
let fEst = 3.4, yawEst = -4.5, txEst = 0.0, aggregate = false;

const elF = document.getElementById('focalLength');
const elY = document.getElementById('rotationYaw');
const elT = document.getElementById('translationX');
const elFV = document.getElementById('fVal');
const elYV = document.getElementById('yawVal');
const elTV = document.getElementById('txVal');
const elRead = document.getElementById('readout');
const elBar = document.getElementById('ebar');
const btnPer = document.getElementById('modePer');
const btnSum = document.getElementById('modeSum');

function refresh() {
  const th = THREE.MathUtils.degToRad(yawEst), c = Math.cos(th), s = Math.sin(th);
  let E = 0;
  for (let i = 0; i < 3; i++) {
    const P = Pw[i];
    const x = P[0] * c + P[2] * s + txEst;
    const y = P[1];
    const z = -P[0] * s + P[2] * c;
    const ex = fEst * x / z, ey = fEst * y / z;
    est[i][0] = ex; est[i][1] = ey;
    const o = obs[i];
    const r = Math.hypot(o[0] - ex, o[1] - ey);
    resv[i] = r; E += r * r;

    const po = IMG(o[0], o[1]), pe = IMG(ex, ey);
    obsDots[i].position.copy(po);
    estDots[i].position.copy(pe);
    setTube(resTubes[i], po, pe);

    pLbl[i].pos.copy(po);
    ePrimeLbl[i].pos.copy(pe);
    rLbl[i].pos.copy(po.clone().add(pe).multiplyScalar(0.5));
    rLbl[i].div.innerHTML = (!aggregate && r > 0.02) ? r.toFixed(3) : '';
  }

  const pts = obs.map(o => IMG(o[0], o[1]));
  setTriVerts(smallTri, pts);
  for (let i = 0; i < 3; i++) setTube(smallOutline[i], pts[i], pts[(i + 1) % 3]);

  const cen = pts[0].clone().add(pts[1]).add(pts[2]).multiplyScalar(1 / 3);
  imgTriad.position.copy(cen);
  setTube(opticalAxis, Corigin, cen);

  if (aggregate) {
    elRead.innerHTML = '<div style="font-size:18px"><i>E</i> = &Sigma;&#8214;p&minus;p&prime;&#8214;<sup>2</sup> = <b>'
      + E.toFixed(4) + '</b></div>'
      + '<div style="font-size:10.5px;color:#555">The single scalar objective minimised by calibration / bundle adjustment.</div>';
  } else {
    elRead.innerHTML =
      '<span style="color:#c1121f"><i>r</i><sub>1</sub> = ' + resv[0].toFixed(3) + '</span> &nbsp; ' +
      '<span style="color:#0b7285"><i>r</i><sub>2</sub> = ' + resv[1].toFixed(3) + '</span> &nbsp; ' +
      '<span style="color:#1a7a35"><i>r</i><sub>3</sub> = ' + resv[2].toFixed(3) + '</span>' +
      '<div style="font-size:10.5px;color:#555"><i>E</i> = &Sigma;<i>r</i><sub>i</sub><sup>2</sup> = ' + E.toFixed(4) + '</div>';
  }
  elBar.style.width = Math.min(100, (E / 0.6) * 100).toFixed(1) + '%';

  elFV.textContent = fEst.toFixed(2);
  elYV.textContent = yawEst.toFixed(1);
  elTV.textContent = txEst.toFixed(2);
}

/* ── screen-aware label placement (keeps p / p′ / residual text uncramped) ── */
const _nd = new THREE.Vector3();
function toPx(v) {
  _nd.copy(v).project(camera);
  return [_nd.x * 0.5 * canvas.clientWidth, -_nd.y * 0.5 * canvas.clientHeight];
}
function updateDotLabels() {
  const po = [], pe = [];
  for (let i = 0; i < 3; i++) { po.push(toPx(obsDots[i].position)); pe.push(toPx(estDots[i].position)); }
  const cx = (po[0][0] + po[1][0] + po[2][0]) / 3;
  const cy = (po[0][1] + po[1][1] + po[2][1]) / 3;
  for (let i = 0; i < 3; i++) {
    let ox = po[i][0] - cx, oy = po[i][1] - cy;
    const ol = Math.hypot(ox, oy) || 1; ox /= ol; oy /= ol;
    const dx = pe[i][0] - po[i][0], dy = pe[i][1] - po[i][1];
    const dl = Math.hypot(dx, dy);
    const big = dl > 9;
    let ux = 0, uy = 0;
    if (big) { ux = dx / dl; uy = dy / dl; }
    let lx = big ? (-ux + ox) : ox, ly = big ? (-uy + oy) : oy;
    const ll = Math.hypot(lx, ly) || 1; lx /= ll; ly /= ll;
    pLbl[i].offset[0] = lx * 30; pLbl[i].offset[1] = ly * 30;
    if (big) {
      ePrimeLbl[i].div.innerHTML = PRIME_HTML[i];
      ePrimeLbl[i].offset[0] = ux * 27; ePrimeLbl[i].offset[1] = uy * 27;
      rLbl[i].offset[0] = -uy * 16; rLbl[i].offset[1] = ux * 16;
    } else {
      ePrimeLbl[i].div.innerHTML = '';
    }
  }
}

/* ── sliders / toggle ─────────────────────────────────────────────────────── */
elF.addEventListener('input', () => { fEst = parseFloat(elF.value); refresh(); });
elY.addEventListener('input', () => { yawEst = parseFloat(elY.value); refresh(); });
elT.addEventListener('input', () => { txEst = parseFloat(elT.value); refresh(); });
document.getElementById('btnTrue').addEventListener('click', () => {
  fEst = F_TRUE; yawEst = 0; txEst = 0;
  elF.value = fEst; elY.value = yawEst; elT.value = txEst;
  refresh();
});
function setMode(agg) {
  aggregate = agg;
  btnPer.classList.toggle('active', !agg);
  btnSum.classList.toggle('active', agg);
