// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (one line per drawn element) ──────────────────────────────
   scene triangle P1P2P3   → Mesh(BufferGeometry 3 verts) MeshBasic #F5A623 DoubleSide
   scene tri outline       → 3 × Cylinder tubes r=0.032u black + sphere joints
   P1/P2/P3 discs          → Sphere(0.18u) colour + Sphere(0.234u) black BackSide rim
   image plane (z = f)     → Mesh(quad x[-1.1,2.3] y[-1.3,2.0]) white opacity .15 DoubleSide
   image plane border      → 4 × Cylinder tubes r=0.024u black
   projected triangle      → Mesh(3 verts) #F5A623 + 3 tubes r=0.018u black
   observed dots p_i       → Sphere(0.075u) colour + black rim + white drag halo
   reprojected dots p_i'   → Sphere(0.058u) colour + black rim
   residual segments       → 3 × Cylinder tubes r=0.022u pure red #FF0000 (rebuilt live)
   projection rays P_i→C   → Line + LineDashedMaterial dash 0.12u / gap 0.08u black
   camera centre C         → Sphere(0.075u) black
   camera triad X_L,Y_L,Z_L→ Cylinder shaft + Cone head, green #39B54A, length 1.5u
   image-plane triad       → Cylinder + Cone, green, length 0.62u, at projected centroid
   optical-axis segment    → Cylinder tube r=0.012u black, C → in-plane triad origin
