const ORANGE = 0xF5A623, C_RED = 0xED1C24, C_CYAN = 0x29ABE2, C_GREEN = 0x22B14C;
const G_TRIAD = 0x39B54A, RES_RED = 0xFF0000;
const S = 0.30;                       // camera-unit → world-unit scale
const F_TRUE = 3.0, ZP = 3.0;
const RECT = { x0: -1.1, x1: 2.3, y0: -1.3, y1: 2.0 };

// camera(X_L,Y_L,Z_L) → world.  z mirrored so the standard isometric pose puts
// depth to the upper-right and reproduces the printed layout.
const Wc = (x, y, z) => new THREE.Vector3(x * S, y * S, -z * S);
const IMG = (u, v) => Wc(u, v, ZP);

// Scene points straight from the geometry notes (well BEYOND the plane at z=3,
// so the big triangle sits clear of the image plane, as in the source).
const Pw = [[4.2, 3.4, 9.0], [1.2, -1.2, 6.0], [-0.4, 3.0, 7.0]];
const COLS = [C_RED, C_CYAN, C_GREEN];
const obs = Pw.map(p => [F_TRUE * p[0] / p[2], F_TRUE * p[1] / p[2]]);  // p1(1.40,1.13) p2(0.60,-0.60) p3(-0.17,1.29)
const est = [[0, 0], [0, 0], [0, 0]];
const resv = [0, 0, 0];

/* ── generic builders ─────────────────────────────────────────────────────── */
const _UP = new THREE.Vector3(0, 1, 0);

function makeTube(radius, color) {
  const geo = new THREE.CylinderGeometry(radius, radius, 1, 12);
  geo.translate(0, 0.5, 0);
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }));
  scene.add(m);
  return m;
}
function setTube(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  mesh.position.copy(a);
  mesh.scale.set(1, Math.max(len, 1e-6), 1);
  if (len > 1e-9) mesh.quaternion.setFromUnitVectors(_UP, dir.clone().normalize());
  mesh.visible = len > 1e-3;
}
function polyTube(points, radius, color) {
  for (let i = 0; i < points.length; i++) {
    setTube(makeTube(radius, color), points[i], points[(i + 1) % points.length]);
  }
  const jg = new THREE.SphereGeometry(radius, 12, 8);
  const jm = new THREE.MeshBasicMaterial({ color });
  points.forEach(p => { const s = new THREE.Mesh(jg, jm); s.position.copy(p); scene.add(s); });
}
function makeDot(radius, color, pos, halo) {
  const g = new THREE.Group();
  const core = new THREE.Mesh(new THREE.SphereGeometry(radius, 24, 16),
    new THREE.MeshBasicMaterial({ color }));
  const rim = new THREE.Mesh(new THREE.SphereGeometry(radius * 1.3, 24, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.BackSide }));
  g.add(core, rim);
