function refresh() {
  const th = THREE.MathUtils.degToRad(yawEst), c = Math.cos(th), s = Math.sin(th);
  let E = 0;
  for (let i = 0; i < 3; i++) {
    const P = Pw[i];
    const x = P[0] * c + P[2] * s + txEst;     // R (yaw) then T
    const y = P[1];
    const z = -P[0] * s + P[2] * c;
    const ex = fEst * x / z, ey = fEst * y / z; // K = diag(f,f,1), principal point 0
    est[i][0] = ex; est[i][1] = ey;
    const o = obs[i];
    const r = Math.hypot(o[0] - ex, o[1] - ey);
    resv[i] = r; E += r * r;

    const po = IMG(o[0], o[1]), pe = IMG(ex, ey);
    obsDots[i].position.copy(po);
    estDots[i].position.copy(pe);
    setTube(resTubes[i], po, pe);

    pLbl[i].pos.copy(po);
    ePrimeLbl[i].pos.copy(pe);
    rLbl[i].pos.copy(po.clone().add(pe).multiplyScalar(0.5));
    rLbl[i].div.innerHTML = (!aggregate && r > 0.03) ? r.toFixed(3) : '';
  }

  const pts = obs.map(o => IMG(o[0], o[1]));
  setTriVerts(smallTri, pts);
  for (let i = 0; i < 3; i++) setTube(smallOutline[i], pts[i], pts[(i + 1) % 3]);

  const cen = pts[0].clone().add(pts[1]).add(pts[2]).multiplyScalar(1 / 3);
  imgTriad.position.copy(cen);
  setTube(opticalAxis, Corigin, cen);

  if (aggregate) {
    elRead.innerHTML = '<div style="font-size:18px"><i>E</i> = &Sigma;&#8214;p&minus;p&prime;&#8214;<sup>2</sup> = <b>'
      + E.toFixed(4) + '</b></div>'
      + '<div style="font-size:10.5px;color:#555">The single scalar objective minimised by calibration / bundle adjustment.</div>';
  } else {
    elRead.innerHTML =
      '<span style="color:#c1121f"><i>r</i><sub>1</sub> = ' + resv[0].toFixed(3) + '</span> &nbsp; ' +
      '<span style="color:#0b7285"><i>r</i><sub>2</sub> = ' + resv[1].toFixed(3) + '</span> &nbsp; ' +
      '<span style="color:#1a7a35"><i>r</i><sub>3</sub> = ' + resv[2].toFixed(3) + '</span>' +
      '<div style="font-size:10.5px;color:#555"><i>E</i> = &Sigma;<i>r</i><sub>i</sub><sup>2</sup> = ' + E.toFixed(4) + '</div>';
  }
  elBar.style.width = Math.min(100, (E / 0.5) * 100).toFixed(1) + '%';

  elFV.textContent = fEst.toFixed(2);
  elYV.textContent = yawEst.toFixed(1);
  elTV.textContent = txEst.toFixed(2);
}

/* ── screen-aware label placement (keeps P / p / p′ / r text uncramped) ───── */
const _nd = new THREE.Vector3();
function toPx(v) {
  _nd.copy(v).project(camera);
  return [_nd.x * 0.5 * canvas.clientWidth, -_nd.y * 0.5 * canvas.clientHeight];
}
function updateLabelOffsets() {
  // Big scene points: push each label radially outward from the triangle centroid.
  const Ps = Pworld.map(toPx);
  const Pc = [(Ps[0][0] + Ps[1][0] + Ps[2][0]) / 3, (Ps[0][1] + Ps[1][1] + Ps[2][1]) / 3];
  for (let i = 0; i < 3; i++) {
    let ox = Ps[i][0] - Pc[0], oy = Ps[i][1] - Pc[1];
    const l = Math.hypot(ox, oy) || 1;
    PLbl[i].offset[0] = (ox / l) * 40;
    PLbl[i].offset[1] = (oy / l) * 40;
  }

  // Image points: p away from its residual, p′ along it, r perpendicular.
  const po = [], pe = [];
  for (let i = 0; i < 3; i++) { po.push(toPx(obsDots[i].position)); pe.push(toPx(estDots[i].position)); }
  const cx = (po[0][0] + po[1][0] + po[2][0]) / 3;
  const cy = (po[0][1] + po[1][1] + po[2][1]) / 3;
  for (let i = 0; i < 3; i++) {
    let ox = po[i][0] - cx, oy = po[i][1] - cy;
    const ol = Math.hypot(ox, oy) || 1; ox /= ol; oy /= ol;
    const dx = pe[i][0] - po[i][0], dy = pe[i][1] - po[i][1];
    const dl = Math.hypot(dx, dy);
    const big = dl > 10;
    let ux = 0, uy = 0;
    if (big) { ux = dx / dl; uy = dy / dl; }
    let lx = big ? (-ux + ox) : ox, ly = big ? (-uy + oy) : oy;
    const ll = Math.hypot(lx, ly) || 1; lx /= ll; ly /= ll;
    pLbl[i].offset[0] = lx * 34; pLbl[i].offset[1] = ly * 34;
    if (big) {
      ePrimeLbl[i].div.innerHTML = PRIME_HTML[i];
      ePrimeLbl[i].offset[0] = ux * 30; ePrimeLbl[i].offset[1] = uy * 30;
      rLbl[i].offset[0] = -uy * 17; rLbl[i].offset[1] = ux * 17;
    } else {
      ePrimeLbl[i].div.innerHTML = '';
    }
  }
}

