/* ── dragging observed points inside the image plane ──────────────────────── */
const dragRay = new THREE.Raycaster();
const dragNdc = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), ZP * S); // world z = -ZP*S
let dragIdx = -1;

function ndcFrom(ev) {
  const r = canvas.getBoundingClientRect();
  dragNdc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  dragNdc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
}
function pickObs(ev) {
  ndcFrom(ev);
  dragRay.setFromCamera(dragNdc, camera);
  const hits = dragRay.intersectObjects(obsDots, true);
  if (!hits.length) return -1;
  let o = hits[0].object;
  while (o) { const k = obsDots.indexOf(o); if (k >= 0) return k; o = o.parent; }
  return -1;
}
window.addEventListener('pointerdown', (ev) => {
  if (ev.target !== canvas) return;
  const k = pickObs(ev);
  if (k >= 0) {
    dragIdx = k;
    controls.enabled = false;
    obsDots[k].userData.halo.visible = true;
    canvas.style.cursor = 'grabbing';
  }
}, true);
window.addEventListener('pointermove', (ev) => {
  if (dragIdx < 0) return;
  ndcFrom(ev);
  dragRay.setFromCamera(dragNdc, camera);
  const hit = new THREE.Vector3();
  if (!dragRay.ray.intersectPlane(dragPlane, hit)) return;
  obs[dragIdx][0] = THREE.MathUtils.clamp(hit.x / S, RECT.x0 + 0.12, RECT.x1 - 0.12);
  obs[dragIdx][1] = THREE.MathUtils.clamp(hit.y / S, RECT.y0 + 0.12, RECT.y1 - 0.12);
  refresh();
});
window.addEventListener('pointerup', () => {
  if (dragIdx >= 0) {
    obsDots[dragIdx].userData.halo.visible = false;
    dragIdx = -1;
    controls.enabled = true;
    canvas.style.cursor = 'default';
  }
});

/* ── guided demo ──────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'Perfect camera model', n: 'Estimated parameters equal the true ones: every p′ lands exactly on p and the red residuals vanish.', s: { f: 3, y: 0, x: 0, agg: false } },
  { t: 'Wrong focal length', n: 'Increasing f pushes every reprojection radially away from the principal point — all residuals point outward together.', s: { f: 3.6, y: 0, x: 0, agg: false } },
  { t: 'Wrong rotation', n: 'A few degrees of yaw error slides the whole predicted triangle sideways: residuals become nearly parallel and similar in length.', s: { f: 3, y: 4, x: 0, agg: false } },
  { t: 'Wrong translation', n: 'A translation error moves near points more than far ones, so the three residuals now have clearly different lengths.', s: { f: 3, y: 0, x: 0.5, agg: false } },
  { t: 'The optimisation objective', n: 'Aggregate mode collapses the three residuals into one scalar E = Σ‖p−p′‖² — drive it to zero by returning to the true pose.', s: { f: 3.4, y: 3, x: 0.3, agg: true } }
];
let stepIdx = -1, tween = null, playing = false, playTimer = null;
const elST = document.getElementById('stepTitle');
const elSX = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i % STEPS.length + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  elST.textContent = (stepIdx + 1) + '. ' + st.t;
  elSX.textContent = st.n;
  setMode(st.s.agg);
  tween = { t0: performance.now(), dur: 750, f0: fEst, y0: yawEst, x0: txEst, f1: st.s.f, y1: st.s.y, x1: st.s.x };
}
function stepTween() {
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
  fEst = tween.f0 + (tween.f1 - tween.f0) * e;
  yawEst = tween.y0 + (tween.y1 - tween.y0) * e;
  txEst = tween.x0 + (tween.x1 - tween.x0) * e;
  elF.value = fEst; elY.value = yawEst; elT.value = txEst;
  refresh();
  if (k >= 1) tween = null;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepPlay').addEventListener('click', (ev) => {
  playing = !playing;
  ev.target.textContent = playing ? 'Pause' : 'Play';
  ev.target.classList.toggle('active', playing);
  clearInterval(playTimer);
  if (playing) { goToStep(stepIdx + 1); playTimer = setInterval(() => goToStep(stepIdx + 1), 4000); }
});

/* ── own loop: tweening + screen-aware label offsets (scaffold renders) ───── */
(function tick() { requestAnimationFrame(tick); stepTween(); updateLabelOffsets(); })();

refresh();
